+package com.example.customers.domain;
+
+import java.text.Normalizer;
+import java.util.Arrays;
+import java.util.EnumSet;
+import java.util.List;
+import java.util.Locale;
+import java.util.Set;
+import java.util.regex.Pattern;
+
+/**
+ * A filter understood by {@link CustomerRepository}.
+ *
+ * <p>A customer matches when every name term appears in its first or last name
+ * (ignoring case and accents) and, if any statuses are given, its status is one
+ * of them.
+ *
+ * @param nameTerms normalized name terms; empty matches every name
+ * @param statuses  accepted statuses; empty accepts every status
+ */
+public record CustomerFilter(List<String> nameTerms, Set<CustomerStatus> statuses) {
+
+    /** A filter that matches every customer. */
+    public static final CustomerFilter NONE = new CustomerFilter(List.of(), Set.of());
+
+    private static final Pattern MARKS = Pattern.compile("\\p{M}+");
+    private static final Pattern WHITESPACE = Pattern.compile("\\s+");
+
+    public CustomerFilter {
+        nameTerms = List.copyOf(nameTerms);
+        statuses = statuses.isEmpty() ? Set.of() : Set.copyOf(EnumSet.copyOf(statuses));
+    }
+
+    /** Builds a filter from the raw text a user typed and the statuses selected. */
+    public static CustomerFilter of(String nameText, Set<CustomerStatus> statuses) {
+        String normalized = normalize(nameText == null ? "" : nameText).strip();
+        List<String> terms = normalized.isEmpty()
+                ? List.of()
+                : Arrays.asList(WHITESPACE.split(normalized));
+        return new CustomerFilter(terms, statuses == null ? Set.of() : statuses);
+    }
+
+    /** Lower-cases and strips accents, so that {@code Mäkinen} becomes {@code makinen}. */
+    public static String normalize(String text) {
+        String decomposed = Normalizer.normalize(text, Normalizer.Form.NFD);
+        return MARKS.matcher(decomposed).replaceAll("").toLowerCase(Locale.ROOT);
+    }
+
+    public boolean isEmpty() {
+        return nameTerms.isEmpty() && statuses.isEmpty();
+    }
+
+    public boolean matches(Customer customer) {
+        if (!statuses.isEmpty() && !statuses.contains(customer.status())) {
+            return false;
+        }
+        if (nameTerms.isEmpty()) {
+            return true;
+        }
+        String first = normalize(customer.firstName());
+        String last = normalize(customer.lastName());
+        return nameTerms.stream().allMatch(term -> first.contains(term) || last.contains(term));
+    }
+}
