+package com.example.customers;
+
+import static org.junit.jupiter.api.Assertions.assertEquals;
+import static org.junit.jupiter.api.Assertions.assertTrue;
+
+import com.example.customers.domain.QueryLog;
+import com.microsoft.playwright.Browser;
+import com.microsoft.playwright.Locator;
+import com.microsoft.playwright.Page;
+import com.microsoft.playwright.Playwright;
+import com.microsoft.playwright.assertions.PlaywrightAssertions;
+import org.junit.jupiter.api.AfterAll;
+import org.junit.jupiter.api.BeforeAll;
+import org.junit.jupiter.api.Test;
+import org.springframework.beans.factory.annotation.Autowired;
+import org.springframework.boot.test.context.SpringBootTest;
+import org.springframework.boot.test.web.server.LocalServerPort;
+
+/** Drives the running application in headless Chromium. */
+@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT)
+class CustomerListBrowserIT {
+
+    private static Playwright playwright;
+    private static Browser browser;
+
+    @LocalServerPort
+    private int port;
+
+    @Autowired
+    private QueryLog queryLog;
+
+    @BeforeAll
+    static void startBrowser() {
+        playwright = Playwright.create();
+        browser = playwright.chromium().launch();
+    }
+
+    @AfterAll
+    static void stopBrowser() {
+        browser.close();
+        playwright.close();
+    }
+
+    @Test
+    void typingIsDebouncedAndUrlFollowsTheFilter() {
+        Page page = browser.newPage();
+        page.navigate("http://localhost:" + port + "/?name=vir&status=ACTIVE,CLOSED");
+        Locator summary = page.locator("#customer-summary");
+        PlaywrightAssertions.assertThat(summary).containsText("Showing");
+        String filtered = summary.textContent();
+        assertTrue(!filtered.equals("Showing 500 of 500"), filtered);
+        PlaywrightAssertions.assertThat(page.locator("vaadin-text-field input")).hasValue("vir");
+        page.navigate("http://localhost:" + port + "/");
+        PlaywrightAssertions.assertThat(summary).hasText("Showing 500 of 500");
+        page.waitForTimeout(500);
+
+        int historyLength = (Integer) page.evaluate("history.length");
+        queryLog.clear();
+        Locator input = page.locator("vaadin-text-field input");
+        input.click();
+        input.pressSequentially("aaltonena", new Locator.PressSequentiallyOptions().setDelay(100));
+        PlaywrightAssertions.assertThat(summary).hasText("Showing 0 of 500");
+        page.waitForTimeout(800);
+        System.out.println("URL after typing: " + page.url());
+        System.out.println("pages=" + queryLog.pageQueries() + " counts=" + queryLog.countQueries());
+        assertTrue(page.url().endsWith("/?name=aaltonena"), page.url());
+        assertTrue(queryLog.countQueries().size() <= 2);
+
+        input.fill("");
+        page.waitForTimeout(800);
+        System.out.println("URL after clearing: " + page.url());
+        assertTrue(page.url().endsWith(":" + port + "/"), page.url());
+        PlaywrightAssertions.assertThat(summary).hasText("Showing 500 of 500");
+
+        page.locator("vaadin-multi-select-combo-box input").click();
+        page.locator("vaadin-multi-select-combo-box-item", new Page.LocatorOptions().setHasText("CLOSED")).click();
+        page.locator("vaadin-multi-select-combo-box-item", new Page.LocatorOptions().setHasText("ACTIVE")).click();
+        page.waitForTimeout(800);
+        System.out.println("URL after status: " + page.url());
+        assertTrue(page.url().endsWith("/?status=ACTIVE,CLOSED"), page.url());
+        assertEquals(historyLength, (int) (Integer) page.evaluate("history.length"),
+                "Editing the filter must not push history entries");
+    }
+}
